#include <iostream>
#include <string>
#include <memory>
#include <stdexcept>

class EmailClient {
public:
    void deliver(const std::string& recipient, const std::string& message) {
        std::cout << "Emailing " << recipient << ": " << message << std::endl;
    }
};

class NotificationSender {
public:
    virtual ~NotificationSender() = default;
    virtual void send(const std::string& recipient, const std::string& message) = 0;
};

class EmailNotificationSender : public NotificationSender {
public:
    explicit EmailNotificationSender(EmailClient& client) : client_(client) {}

    void send(const std::string& recipient, const std::string& message) override {
        client_.deliver(recipient, message);
    }

private:
    EmailClient& client_;
};

class NotificationFactory {
public:
    static std::unique_ptr<NotificationSender> create(const std::string& channel, EmailClient& client) {
        if (channel == "email") {
            return std::make_unique<EmailNotificationSender>(client);
        }
        throw std::invalid_argument("Unknown channel: " + channel);
    }
};

class NotificationService {
public:
    explicit NotificationService(std::unique_ptr<NotificationSender> sender)
        : sender_(std::move(sender)) {}

    void notifyOrderConfirmed(const std::string& email, const std::string& orderId) {
        sender_->send(email, "Order " + orderId + " confirmed");
    }

private:
    std::unique_ptr<NotificationSender> sender_;
};

int main() {
    EmailClient client;
    NotificationService service(NotificationFactory::create("email", client));
    service.notifyOrderConfirmed("buyer@example.com", "1001");
    return 0;
}

